<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="d-flex justify-content-between align-items-center mb-3"><div><h2>Data Pegawai</h2><p class="text-secondary mb-0">Master pegawai NEURO ABSENSI</p></div><a class="btn btn-primary" href="/pegawai/baru">Tambah pegawai</a></div><div class="card p-3"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Kode</th><th>Nama</th><th>Jabatan</th><th>Status</th></tr></thead><tbody><?php foreach ($employees as $employee): ?><tr><td><?= esc($employee['employee_code']) ?></td><td><?= esc($employee['full_name']) ?></td><td><?= esc($employee['position'] ?? '-') ?></td><td><?= $employee['is_active'] ? 'Aktif' : 'Nonaktif' ?></td></tr><?php endforeach ?><?php if (empty($employees)): ?><tr><td colspan="4" class="text-center text-secondary py-4">Belum ada data pegawai.</td></tr><?php endif ?></tbody></table></div></div><?= $this->endSection() ?>